func TestAdaptImportExistingSemanticsPreserved(t *testing.T) {
	t.Run("empty file", func(t *testing.T) {
		dir := t.TempDir()
		writeImportFile(t, dir, "empty.caddy", "")
		writeImportFile(t, dir, "spaces.caddy", "  \n\t\n")
