func TestAdaptWarningOrderMainThenImports(t *testing.T) {
	dir := t.TempDir()
	writeImportFile(t, dir, "imp.caddy", "respond  \"imp\"\n")

	// main file's first difference is on line 3
	mainBody := ":8080 {\n\trespond \"x\"\n\tbad  y\n}\n"
