func TestAdaptFormattingDoesNotChangeJSON(t *testing.T) {
	dir := t.TempDir()
	mainBody := ":8080 {\n\timport imp.caddy\n}\n"

	writeImportFile(t, dir, "imp.caddy", "respond  \"ok\"\n")
